/**
 * Shared types for the Runway Gantt CLI.
 *
 * Co-located with the gantt module under scripts/lib/gantt/.
 */

import type { projects, weekItems, clients } from "@/lib/db/runway-schema";

export type ProjectRow = typeof projects.$inferSelect;
export type WeekItemRow = typeof weekItems.$inferSelect;
export type ClientRow = typeof clients.$inferSelect;

// ── Resolution ───────────────────────────────────────────

export type ResolvedSubject =
  | { kind: "wrapper"; project: ProjectRow; childProjects: ProjectRow[] }
  | { kind: "l1"; project: ProjectRow };

export type ResolveProjectResult =
  | { ok: true; subject: ResolvedSubject }
  | { ok: false; error: string; available?: string[] };

export type ResolveClientResult =
  | { ok: true; client: ClientRow; topLevelProjects: ProjectRow[] }
  | { ok: false; error: string; available?: string[] };

/**
 * Entity resolution for the Runway Gantt CLI.
 *
 * Resolves a project or client from a name/id input, then classifies the
 * resolved project as a wrapper view (retainer with child L1s) or an L1
 * view (everything else, including sub-projects and degenerate retainers).
 *
 * Pure helpers (`resolveProjectFromList`, `resolveClientFromList`,
 * `classifyProject`) are exported for unit testing without a DB.
 */

import { drizzle } from "drizzle-orm/libsql";
import { and, eq, isNull } from "drizzle-orm";
import { clients, projects } from "@/lib/db/runway-schema";
import { fuzzyMatch } from "@/lib/runway/operations-utils";
import type {
  ClientRow,
  ProjectRow,
  ResolveClientResult,
  ResolveProjectResult,
  ResolvedSubject,
} from "./types";

type DrizzleDb = ReturnType<typeof drizzle>;

// ── Pure helpers (testable without DB) ────────────────────

export function classifyProject(
  project: ProjectRow,
  childProjects: ProjectRow[],
): ResolvedSubject {
  const isWrapper =
    project.parentProjectId === null &&
    project.engagementType === "retainer" &&
    childProjects.length > 0;
  return isWrapper
    ? { kind: "wrapper", project, childProjects }
    : { kind: "l1", project };
}

function displayLabel(project: ProjectRow, clientsById: Map<string, ClientRow>): string {
  const clientName = clientsById.get(project.clientId)?.name ?? "?";
  return `${clientName}: ${project.name}`;
}

export function resolveProjectFromList(
  projectList: ProjectRow[],
  clientsById: Map<string, ClientRow>,
  input: string,
):
  | { ok: true; project: ProjectRow }
  | { ok: false; error: string; available?: string[] } {
  // 1. Exact id match
  const idHit = projectList.find((p) => p.id === input);
  if (idHit) return { ok: true, project: idHit };

  // 2. Fuzzy match on plain name
  const nameResult = fuzzyMatch(projectList, input, (p) => p.name);
  if (nameResult.kind === "match") return { ok: true, project: nameResult.value };

  // 3. Fuzzy match on "Client / Name" — catches inputs like "Convergix CDS"
  const qualifiedResult = fuzzyMatch(
    projectList,
    input,
    (p) => `${clientsById.get(p.clientId)?.name ?? ""} / ${p.name}`,
  );
  if (qualifiedResult.kind === "match") return { ok: true, project: qualifiedResult.value };

  // 4. Either side ambiguous → return options
  if (nameResult.kind === "ambiguous" || qualifiedResult.kind === "ambiguous") {
    const options =
      nameResult.kind === "ambiguous"
        ? nameResult.options
        : qualifiedResult.kind === "ambiguous"
          ? qualifiedResult.options
          : [];
    const display = options.map((p) => displayLabel(p, clientsById));
    return {
      ok: false,
      error: `Multiple projects match '${input}': ${display.join(", ")}. Which one?`,
      available: display,
    };
  }

  return {
    ok: false,
    error: `Project '${input}' not found.`,
    available: projectList.map((p) => displayLabel(p, clientsById)),
  };
}

export function resolveClientFromList(
  clientList: ClientRow[],
  input: string,
):
  | { ok: true; client: ClientRow }
  | { ok: false; error: string; available?: string[] } {
  // 1. Exact id
  const idHit = clientList.find((c) => c.id === input);
  if (idHit) return { ok: true, client: idHit };
  // 2. Exact slug (case-insensitive)
  const slugHit = clientList.find((c) => c.slug.toLowerCase() === input.toLowerCase());
  if (slugHit) return { ok: true, client: slugHit };
  // 3. Fuzzy on name
  const result = fuzzyMatch(clientList, input, (c) => c.name);
  if (result.kind === "match") return { ok: true, client: result.value };
  if (result.kind === "ambiguous") {
    const options = result.options.map((c) => c.name);
    return {
      ok: false,
      error: `Multiple clients match '${input}': ${options.join(", ")}. Which one?`,
      available: options,
    };
  }
  return {
    ok: false,
    error: `Client '${input}' not found.`,
    available: clientList.map((c) => c.name),
  };
}

// ── DB-coupled wrappers ───────────────────────────────────

export async function resolveProject(
  db: DrizzleDb,
  input: string,
): Promise<ResolveProjectResult> {
  const [allClients, allProjects] = await Promise.all([
    db.select().from(clients),
    db.select().from(projects),
  ]);
  const clientsById = new Map(allClients.map((c) => [c.id, c]));

  const result = resolveProjectFromList(allProjects, clientsById, input);
  if (!result.ok) return result;

  const childProjects = allProjects.filter(
    (p) => p.parentProjectId === result.project.id,
  );
  return { ok: true, subject: classifyProject(result.project, childProjects) };
}

export async function resolveClient(
  db: DrizzleDb,
  input: string,
): Promise<ResolveClientResult> {
  const allClients = await db.select().from(clients);
  const result = resolveClientFromList(allClients, input);
  if (!result.ok) return result;

  const topLevelProjects = await db
    .select()
    .from(projects)
    .where(
      and(eq(projects.clientId, result.client.id), isNull(projects.parentProjectId)),
    );

  return { ok: true, client: result.client, topLevelProjects };
}

import { describe, expect, it } from "vitest";
import {
  classifyProject,
  resolveClientFromList,
  resolveProjectFromList,
} from "./resolve-entity";
import type { ClientRow, ProjectRow } from "./types";

const NOW = new Date("2026-04-28T00:00:00Z");

function makeClient(overrides: Partial<ClientRow> = {}): ClientRow {
  return {
    id: "c-default",
    name: "Default Client",
    slug: "default-client",
    nicknames: null,
    contractValue: null,
    contractTerm: null,
    contractStatus: null,
    team: null,
    clientContacts: null,
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

function makeProject(overrides: Partial<ProjectRow> = {}): ProjectRow {
  return {
    id: "p-default",
    clientId: "c-default",
    name: "Default Project",
    status: null,
    category: null,
    owner: null,
    resources: null,
    waitingOn: null,
    dueDate: null,
    startDate: null,
    endDate: null,
    contractStart: null,
    contractEnd: null,
    engagementType: null,
    parentProjectId: null,
    notes: null,
    staleDays: null,
    sortOrder: 0,
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

describe("classifyProject", () => {
  const baseRetainer = makeProject({
    id: "wrapper",
    engagementType: "retainer",
    parentProjectId: null,
  });
  const child = makeProject({ id: "child", parentProjectId: "wrapper" });

  it("classifies retainer with children as wrapper", () => {
    const result = classifyProject(baseRetainer, [child]);
    expect(result.kind).toBe("wrapper");
    if (result.kind === "wrapper") {
      expect(result.childProjects).toHaveLength(1);
    }
  });

  it("treats retainer with no children as L1 (degenerate)", () => {
    const result = classifyProject(baseRetainer, []);
    expect(result.kind).toBe("l1");
  });

  it("treats non-retainer engagement as L1 even with children", () => {
    const project = makeProject({
      id: "px",
      engagementType: "project",
      parentProjectId: null,
    });
    const result = classifyProject(project, [child]);
    expect(result.kind).toBe("l1");
  });

  it("treats sub-project (parentProjectId set) as L1", () => {
    const subProject = makeProject({
      id: "sub",
      engagementType: "retainer",
      parentProjectId: "wrapper",
    });
    const result = classifyProject(subProject, []);
    expect(result.kind).toBe("l1");
  });

  it("treats null engagementType as L1", () => {
    const project = makeProject({ engagementType: null, parentProjectId: null });
    const result = classifyProject(project, [child]);
    expect(result.kind).toBe("l1");
  });
});

describe("resolveProjectFromList", () => {
  const ag1 = makeClient({ id: "c-ag1", name: "AG1", slug: "ag1" });
  const cgx = makeClient({ id: "c-cgx", name: "Convergix", slug: "convergix" });
  const clientsById = new Map([
    [ag1.id, ag1],
    [cgx.id, cgx],
  ]);

  const wrapper = makeProject({
    id: "p-ag1-wrap",
    clientId: ag1.id,
    name: "AG1",
    engagementType: "retainer",
  });
  const proContent = makeProject({
    id: "p-ag1-pro",
    clientId: ag1.id,
    name: "AG1 PRO Content",
    parentProjectId: wrapper.id,
  });
  const cdsMessaging = makeProject({
    id: "p-cgx-cds",
    clientId: cgx.id,
    name: "CDS Messaging",
  });

  const allProjects = [wrapper, proContent, cdsMessaging];

  it("matches by exact id", () => {
    const result = resolveProjectFromList(allProjects, clientsById, "p-cgx-cds");
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.project.id).toBe("p-cgx-cds");
  });

  it("matches by exact name", () => {
    const result = resolveProjectFromList(allProjects, clientsById, "CDS Messaging");
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.project.id).toBe("p-cgx-cds");
  });

  it("matches by qualified Client / Name", () => {
    const result = resolveProjectFromList(
      allProjects,
      clientsById,
      "Convergix / CDS Messaging",
    );
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.project.id).toBe("p-cgx-cds");
  });

  it("returns disambiguation list when multiple names share a substring", () => {
    const otherAg1 = makeProject({
      id: "p-ag1-other",
      clientId: ag1.id,
      name: "AG1 Social Drafts",
    });
    const result = resolveProjectFromList(
      [...allProjects, otherAg1],
      clientsById,
      "AG1",
    );
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error).toMatch(/Multiple projects match 'AG1'/);
      expect(result.available).toEqual(
        expect.arrayContaining([
          "AG1: AG1",
          "AG1: AG1 PRO Content",
          "AG1: AG1 Social Drafts",
        ]),
      );
    }
  });

  it("returns not-found error with full list on no match", () => {
    const result = resolveProjectFromList(allProjects, clientsById, "Nope");
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error).toBe("Project 'Nope' not found.");
      expect(result.available).toContain("AG1: AG1");
    }
  });

  it("renders unknown clientId as '?' in disambiguation labels", () => {
    const orphan = makeProject({
      id: "p-orphan",
      clientId: "c-missing",
      name: "Orphan Project",
    });
    const result = resolveProjectFromList([orphan], clientsById, "Nope");
    expect(result.ok).toBe(false);
    if (!result.ok) expect(result.available).toContain("?: Orphan Project");
  });
});

describe("resolveClientFromList", () => {
  const ag1 = makeClient({ id: "c-ag1", name: "AG1", slug: "ag1" });
  const cgx = makeClient({ id: "c-cgx", name: "Convergix", slug: "convergix" });
  const conv2 = makeClient({ id: "c-conv2", name: "Convergent Group", slug: "convergent-group" });
  const all = [ag1, cgx, conv2];

  it("matches by exact id", () => {
    const result = resolveClientFromList(all, "c-cgx");
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.client.id).toBe("c-cgx");
  });

  it("matches by exact slug (case-insensitive)", () => {
    const result = resolveClientFromList(all, "AG1");
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.client.id).toBe("c-ag1");
  });

  it("matches by fuzzy name when no slug or id hits", () => {
    const result = resolveClientFromList(all, "Convergix");
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.client.id).toBe("c-cgx");
  });

  it("returns disambiguation when fuzzy match is ambiguous", () => {
    // "conver" matches both "Convergix" and "Convergent Group" via startsWith
    const result = resolveClientFromList(all, "Conver");
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error).toMatch(/Multiple clients match 'Conver'/);
      expect(result.available).toEqual(
        expect.arrayContaining(["Convergix", "Convergent Group"]),
      );
    }
  });

  it("returns not-found error on no match", () => {
    const result = resolveClientFromList(all, "Nope");
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error).toBe("Client 'Nope' not found.");
      expect(result.available).toEqual(["AG1", "Convergix", "Convergent Group"]);
    }
  });
});

