/**
 * Deterministic data-quality detectors for the Gantt CLI.
 *
 * Pure functions. No DB, no I/O, no LLM. Each detector returns the issues
 * for one scope:
 *
 *   detectL1Issues(entity, weekItemCount)            → chart-level L1 alerts
 *   detectWrapperIssues(wrapper, children, orphans)  → chart-level wrapper alerts
 *   detectChildProjectIssues(child, wrapper)         → wrapper-view row issues
 *   detectWeekItemIssues(item, parent, todayISO)     → L1-view row issues
 *   detectAllIssues(raw, rows, today)                → top-level dispatcher
 *
 * Row issues are split into `inline` (shown on the row itself, e.g. red
 * `null – null`) and `subRow` (shown as an alert sub-row beneath the row).
 */

import type {
  AnnotatedRow,
  GanttRow,
  Issue,
  ProjectRow,
  RawData,
  RowIssues,
  WeekItemRow,
} from "./types";

// ── Operator-confirmed enum lists ─────────────────────────

const VALID_ENGAGEMENT_TYPES = new Set(["retainer", "project"]);
const ACTIVE_WI_STATUSES = new Set(["in-progress", "scheduled", "at-risk"]);
const TERMINAL_WI_STATUSES = new Set(["completed", "canceled"]);

function isBlank(v: string | null | undefined): boolean {
  return v === null || v === undefined || v === "";
}

// ── Inline date issues (shared between project + weekItem rows) ──

function detectInlineDates(
  startDate: string | null,
  endDate: string | null,
  prefix: "row" | "wi",
): Issue[] {
  if (startDate === null && endDate === null) {
    return [
      {
        code: `${prefix}-both-dates-null` as const,
        message: "Both start and end dates are null.",
      },
    ];
  }
  if (startDate === null) {
    return [{ code: `${prefix}-only-start-null` as const, message: "Start date is null." }];
  }
  if (endDate === null) {
    return [{ code: `${prefix}-only-end-null` as const, message: "End date is null." }];
  }
  if (endDate < startDate) {
    return [
      {
        code: `${prefix}-end-before-start` as const,
        message: `End date (${endDate}) is before start date (${startDate}).`,
      },
    ];
  }
  return [];
}

// ── Per-row detectors ────────────────────────────────────

export function detectChildProjectIssues(
  child: ProjectRow,
  wrapper: ProjectRow,
): RowIssues {
  const inline = detectInlineDates(child.startDate, child.endDate, "row");
  const subRow: Issue[] = [];

  if (child.category === "active" && isBlank(child.owner)) {
    subRow.push({
      code: "child-active-null-owner",
      message: "Active project has no owner.",
    });
  }

  if (child.parentProjectId === null) {
    subRow.push({
      code: "child-orphan",
      message: "Child project has parentProjectId=null (expected to point at the wrapper).",
    });
  }

  // Parent-child date mismatch — wrapper range derived from entity start/end OR contract dates.
  const wrapperStart = wrapper.startDate ?? wrapper.contractStart;
  const wrapperEnd = wrapper.endDate ?? wrapper.contractEnd;
  if (wrapperStart && wrapperEnd) {
    if (
      (child.startDate && child.startDate < wrapperStart) ||
      (child.endDate && child.endDate > wrapperEnd)
    ) {
      subRow.push({
        code: "child-parent-date-mismatch",
        message: `Child range (${child.startDate ?? "null"} – ${child.endDate ?? "null"}) outside wrapper range (${wrapperStart} – ${wrapperEnd}).`,
      });
    }
  }

  if (
    child.startDate &&
    child.endDate &&
    child.endDate < child.startDate
  ) {
    subRow.push({
      code: "child-end-before-start",
      message: `End (${child.endDate}) is before start (${child.startDate}).`,
    });
  }

  // Status / category mismatch — narrow rule: completed must pair with completed.
  if (child.status === "completed" && child.category && child.category !== "completed") {
    subRow.push({
      code: "child-status-category-mismatch",
      message: `Status 'completed' but category '${child.category}'.`,
    });
  } else if (child.category === "completed" && child.status && child.status !== "completed") {
    subRow.push({
      code: "child-status-category-mismatch",
      message: `Category 'completed' but status '${child.status}'.`,
    });
  }

  if (child.status === "awaiting-client" && isBlank(child.waitingOn)) {
    subRow.push({
      code: "child-awaiting-null-waiting-on",
      message: "Status 'awaiting-client' but waitingOn is null.",
    });
  }

  if (wrapper.engagementType && isBlank(child.engagementType)) {
    subRow.push({
      code: "child-null-engagement-when-parent-set",
      message: `Wrapper engagementType is '${wrapper.engagementType}' but child engagementType is null.`,
    });
  }

  return { inline, subRow };
}

export function detectWeekItemIssues(
  item: WeekItemRow,
  parent: ProjectRow,
  todayISO: string,
): RowIssues {
  const inline = detectInlineDates(item.startDate, item.endDate, "wi");
  const subRow: Issue[] = [];

  // Per operator: null status is treated as 'scheduled' for bucketing/filtering.
  const effectiveStatus = item.status ?? "scheduled";

  if (ACTIVE_WI_STATUSES.has(effectiveStatus) && isBlank(item.owner)) {
    subRow.push({
      code: "wi-active-null-owner",
      message: `Status '${effectiveStatus}' but owner is null.`,
    });
  }

  if (
    item.endDate &&
    item.endDate < todayISO &&
    !TERMINAL_WI_STATUSES.has(effectiveStatus)
  ) {
    subRow.push({
      code: "wi-overdue",
      message: `End date (${item.endDate}) is in the past and status is '${effectiveStatus}'.`,
    });
  }

  // wi-outside-parent-range — only fires when parent has BOTH dates set.
  if (parent.startDate && parent.endDate) {
    const startsBefore = item.startDate && item.startDate < parent.startDate;
    const endsAfter = item.endDate && item.endDate > parent.endDate;
    if (startsBefore || endsAfter) {
      subRow.push({
        code: "wi-outside-parent-range",
        message: `Item range (${item.startDate ?? "null"} – ${item.endDate ?? "null"}) outside parent project range (${parent.startDate} – ${parent.endDate}).`,
      });
    }
  }

  return { inline, subRow };
}

// ── Chart-level detectors ─────────────────────────────────

export function detectL1Issues(entity: ProjectRow, weekItemCount: number): Issue[] {
  const issues: Issue[] = [];

  if (entity.startDate === null || entity.endDate === null) {
    const which =
      entity.startDate === null && entity.endDate === null
        ? "startDate and endDate"
        : entity.startDate === null
          ? "startDate"
          : "endDate";
    issues.push({ code: "l1-null-dates", message: `Project has null ${which}.` });
  }

  if (entity.engagementType === "retainer") {
    if (isBlank(entity.contractStart) || isBlank(entity.contractEnd)) {
      issues.push({
        code: "l1-retainer-null-contract",
        message: "Retainer has null contractStart or contractEnd.",
      });
    }
  }

  if (isBlank(entity.engagementType) || !VALID_ENGAGEMENT_TYPES.has(entity.engagementType ?? "")) {
    issues.push({
      code: "l1-null-engagement-type",
      message: isBlank(entity.engagementType)
        ? "engagementType is null."
        : `Unexpected engagementType '${entity.engagementType}' (expected 'retainer' or 'project').`,
    });
  }

  if (isBlank(entity.category) || isBlank(entity.status)) {
    const which =
      isBlank(entity.category) && isBlank(entity.status)
        ? "category and status"
        : isBlank(entity.category)
          ? "category"
          : "status";
    issues.push({ code: "l1-null-category-or-status", message: `${which} is null.` });
  }

  if (entity.status === "awaiting-client" && isBlank(entity.waitingOn)) {
    issues.push({
      code: "l1-awaiting-null-waiting-on",
      message: "Status 'awaiting-client' but waitingOn is null.",
    });
  }

  // dueDate set but endDate null (or vice versa)
  const dueSet = !isBlank(entity.dueDate);
  const endSet = !isBlank(entity.endDate);
  if (dueSet !== endSet) {
    issues.push({
      code: "l1-due-end-mismatch",
      message: dueSet
        ? "dueDate is set but endDate is null."
        : "endDate is set but dueDate is null.",
    });
  }

  if (weekItemCount === 0 && isBlank(entity.owner)) {
    issues.push({
      code: "l1-no-weekitems-no-owner",
      message: "Project has no weekItems and no owner.",
    });
  }

  return issues;
}

export function detectWrapperIssues(
  wrapper: ProjectRow,
  children: ProjectRow[],
  orphanWeekItems: { id: string; title: string }[],
): Issue[] {
  const issues: Issue[] = [];

  if (isBlank(wrapper.contractStart) || isBlank(wrapper.contractEnd)) {
    issues.push({
      code: "wrapper-null-contract",
      message: "Wrapper has null contractStart or contractEnd.",
    });
  }

  if (children.length === 0) {
    issues.push({
      code: "wrapper-no-children",
      message: "Wrapper has no child projects.",
    });
  }

  if (wrapper.engagementType !== "retainer") {
    issues.push({
      code: "wrapper-bad-engagement-type",
      message: `Wrapper engagementType is '${wrapper.engagementType ?? "null"}', expected 'retainer'.`,
    });
  }

  // wrapper-range-misses-children — wrapper range derived from entity start/end OR contract dates
  const wrapperStart = wrapper.startDate ?? wrapper.contractStart;
  const wrapperEnd = wrapper.endDate ?? wrapper.contractEnd;
  if (wrapperStart && wrapperEnd) {
    const offending: string[] = [];
    for (const c of children) {
      if (c.startDate && c.startDate < wrapperStart) {
        offending.push(`${c.name} starts ${c.startDate}`);
      }
      if (c.endDate && c.endDate > wrapperEnd) {
        offending.push(`${c.name} ends ${c.endDate}`);
      }
    }
    if (offending.length > 0) {
      issues.push({
        code: "wrapper-range-misses-children",
        message: `Wrapper range (${wrapperStart} – ${wrapperEnd}) doesn't cover: ${offending.join("; ")}.`,
      });
    }
  }

  if (!isBlank(wrapper.contractStart) && !isBlank(wrapper.contractEnd)) {
    const mismatched: string[] = [];
    for (const c of children) {
      if (!isBlank(c.contractStart) && c.contractStart !== wrapper.contractStart) {
        mismatched.push(`${c.name} contractStart ${c.contractStart}`);
      }
      if (!isBlank(c.contractEnd) && c.contractEnd !== wrapper.contractEnd) {
        mismatched.push(`${c.name} contractEnd ${c.contractEnd}`);
      }
    }
    if (mismatched.length > 0) {
      issues.push({
        code: "wrapper-child-contract-mismatch",
        message: `Children with mismatched contract dates: ${mismatched.join("; ")}.`,
      });
    }
  }

  if (orphanWeekItems.length > 0) {
    const idList = orphanWeekItems.map((w) => `${w.id} (${w.title})`).join(", ");
    issues.push({
      code: "wrapper-has-orphan-weekitems",
      message: `Wrapper has ${orphanWeekItems.length} weekItem(s) attached directly — only child project rows are rendered. Move or delete: ${idList}`,
    });
  }

  return issues;
}

// ── Top-level dispatcher ──────────────────────────────────

export function detectAllIssues(
  raw: RawData,
  rows: GanttRow[],
  today: Date = new Date(),
): { rows: AnnotatedRow[]; chartIssues: Issue[] } {
  const todayISO = today.toISOString().slice(0, 10);

  if (raw.kind === "wrapper") {
    const chartIssues = detectWrapperIssues(raw.entity, raw.children, raw.orphanWeekItems);
    const childById = new Map(raw.children.map((c) => [c.id, c]));
    const annotated: AnnotatedRow[] = rows.map((row) => {
      if (row.kind !== "project") {
        return { ...row, inline: [], subRow: [] };
      }
      const child = childById.get(row.id);
      if (!child) return { ...row, inline: [], subRow: [] };
      const result = detectChildProjectIssues(child, raw.entity);
      return { ...row, ...result };
    });
    return { rows: annotated, chartIssues };
  }

  // L1 view
  const chartIssues = detectL1Issues(raw.entity, raw.children.length);
  const itemById = new Map(raw.children.map((c) => [c.id, c]));
  const annotated: AnnotatedRow[] = rows.map((row) => {
    if (row.kind !== "weekitem") {
      return { ...row, inline: [], subRow: [] };
    }
    const item = itemById.get(row.id);
    if (!item) return { ...row, inline: [], subRow: [] };
    const result = detectWeekItemIssues(item, raw.entity, todayISO);
    return { ...row, ...result };
  });
  return { rows: annotated, chartIssues };
}

import { describe, expect, it } from "vitest";
import {
  detectAllIssues,
  detectChildProjectIssues,
  detectL1Issues,
  detectWeekItemIssues,
  detectWrapperIssues,
} from "./detect-issues";
import { transformRows } from "./transform-rows";
import type {
  ClientRow,
  IssueCode,
  ProjectRow,
  RawData,
  WeekItemRow,
} from "./types";

const NOW = new Date("2026-04-28T00:00:00Z");
const TODAY_ISO = "2026-04-28";

function makeClient(overrides: Partial<ClientRow> = {}): ClientRow {
  return {
    id: "c1",
    name: "Client",
    slug: "client",
    nicknames: null,
    contractValue: null,
    contractTerm: null,
    contractStatus: null,
    team: null,
    clientContacts: null,
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

function makeProject(overrides: Partial<ProjectRow> = {}): ProjectRow {
  return {
    id: "p1",
    clientId: "c1",
    name: "Project",
    status: null,
    category: null,
    owner: null,
    resources: null,
    waitingOn: null,
    dueDate: null,
    startDate: null,
    endDate: null,
    contractStart: null,
    contractEnd: null,
    engagementType: null,
    parentProjectId: null,
    notes: null,
    staleDays: null,
    sortOrder: 0,
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

function makeWeekItem(overrides: Partial<WeekItemRow> = {}): WeekItemRow {
  return {
    id: "w1",
    projectId: "p1",
