export type RowIssues = { inline: Issue[]; subRow: Issue[] };

export type AnnotatedRow = GanttRow & RowIssues;

// ── Summary + assembled chart data ───────────────────────

export type CodeRef = { id: string; title: string };

export type Summary = {
  rowsWithGaps: number; // rows where inline.length + subRow.length > 0
  totalRows: number;
  chartIssueCount: number;
  byCode: Record<string, CodeRef[]>; // keyed by IssueCode string
};

export type GanttData = {
  raw: RawData;
  rows: AnnotatedRow[];
  chartIssues: Issue[];
  axis: AxisParams;
  headerRange: string; // formatted "4/17 – 5/11" / "null – null" / "5/11"
  generatedAt: string; // YYYY-MM-DD
  summary: Summary;
};

content:
/**
 * Counter — summarize chart-level + row-level issues into a counter line and
 * itemized breakdown for the rendered template.
 *
 * `summarize` and `formatCounterMarkup` are needed by the template (Wave 5).
 * `formatCounterConsole` (Wave 6) extends this for the CLI's stdout mirror.
 */

import type { ReactNode } from "react";
import type { AnnotatedRow, GanttData, Issue, ProjectRow, Summary } from "./types";

/**
 * Walk all issues (chart + row) and roll up:
 *   - rowsWithGaps    : rows with at least one inline OR subRow issue
 *   - totalRows       : data.rows.length
 *   - chartIssueCount : data.chartIssues.length
 *   - byCode          : code → list of affected entities
 *
 * For row-level codes, the entity is the row's id+title. For chart-level
 * codes, the entity is the chart subject (raw.entity) — same id+title for
 * every chart-level fire on a given run.
 */
export function summarize(input: {
  rows: AnnotatedRow[];
  chartIssues: Issue[];
  entity: ProjectRow;
}): Summary {
  const { rows, chartIssues, entity } = input;
  const byCode: Record<string, { id: string; title: string }[]> = {};

  let rowsWithGaps = 0;
  for (const row of rows) {
    if (row.inline.length + row.subRow.length === 0) continue;
    rowsWithGaps += 1;
    for (const issue of [...row.inline, ...row.subRow]) {
      if (!byCode[issue.code]) byCode[issue.code] = [];
      byCode[issue.code].push({ id: row.id, title: row.title });
    }
  }
  for (const issue of chartIssues) {
    if (!byCode[issue.code]) byCode[issue.code] = [];
    byCode[issue.code].push({ id: entity.id, title: entity.name });
  }

  return {
    rowsWithGaps,
    totalRows: rows.length,
    chartIssueCount: chartIssues.length,
    byCode,
  };
}

/** Headline string. Omits a clause when its count is zero. */
export function formatHeadline(summary: Summary): string {
  const rowClause = `${summary.rowsWithGaps} of ${summary.totalRows} rows have data gaps`;
  const chartClause = `${summary.chartIssueCount} chart-level issue${summary.chartIssueCount === 1 ? "" : "s"}`;
  if (summary.rowsWithGaps === 0 && summary.chartIssueCount === 0) {
    return `0 of ${summary.totalRows} rows have data gaps`;
  }
  if (summary.chartIssueCount === 0) return rowClause;
  if (summary.rowsWithGaps === 0) return `${rowClause} + ${chartClause}`;
  return `${rowClause} + ${chartClause}`;
}

/** Sorted, friendly-labelled itemized lines. Keyed by IssueCode. */
function entries(summary: Summary): { code: string; refs: { id: string; title: string }[] }[] {
  return Object.keys(summary.byCode)
    .sort()
    .map((code) => ({ code, refs: summary.byCode[code] }));
}

/** Render the counter slot for the GanttTemplate. */
export function formatCounterMarkup(summary: Summary): ReactNode {
  const items = entries(summary);
  return (
    <section className="counter">
      <h2 className="counter-headline">{formatHeadline(summary)}</h2>
      {items.length > 0 && (
        <ul className="counter-breakdown">
          {items.map(({ code, refs }) => (
            <li key={code}>
              <code className="issue-code">{code}</code>
              <span className="issue-count"> ({refs.length})</span>
              <span className="issue-refs">: {refs.map((r) => r.title).join(", ")}</span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

/**
 * Static HTML template for a single Gantt render. Rendered server-side via
 * `renderToStaticMarkup`. Self-contained: inline `<style>` block, no JS.
 *
 * Render order (operator-locked):
 *   1. Header (name + raw date range + generated stamp + legend)
 *   2. Counter line (split row-gap count + chart-issue count)
 *   3. Counter itemized breakdown
 *   4. Alert section (chart-level alerts shown again in full)
 *   5. Gantt body (table-style row + sub-row alerts)
 */

import { renderToStaticMarkup } from "react-dom/server";
import { formatCounterMarkup } from "./counter";
import { formatDateRange } from "./transform-rows";
import type { AnnotatedRow, AxisParams, GanttData, Issue } from "./types";

// ── Bar / marker geometry ─────────────────────────────────

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function parseISO(s: string): Date {
  return new Date(`${s}T00:00:00Z`);
}

function dayDiff(from: string, to: string): number {
  return Math.round((parseISO(to).getTime() - parseISO(from).getTime()) / MS_PER_DAY);
}

function clampPct(n: number): number {
  if (Number.isNaN(n)) return 0;
  return Math.max(0, Math.min(100, n));
}

type BarGeometry =
  | { kind: "bar"; left: number; width: number }
  | { kind: "milestone"; left: number }
  | { kind: "none" };

export function computeBarGeometry(row: AnnotatedRow, axis: AxisParams): BarGeometry {
  if (axis.kind === "no-axis") return { kind: "none" };
  if (row.startDate === null || row.endDate === null) return { kind: "none" };
  if (row.endDate < row.startDate) return { kind: "none" }; // bad pair → no bar
  const totalDays = dayDiff(axis.start, axis.end);
  if (totalDays <= 0) return { kind: "none" };
  if (row.startDate === row.endDate) {
    const left = clampPct((dayDiff(axis.start, row.startDate) / totalDays) * 100);
    return { kind: "milestone", left };
  }
  const left = clampPct((dayDiff(axis.start, row.startDate) / totalDays) * 100);
  const widthDays = dayDiff(row.startDate, row.endDate) + 1; // inclusive end
  const width = clampPct((widthDays / totalDays) * 100);
  return { kind: "bar", left, width };
}

export function computeTodayPosition(axis: AxisParams): number | null {
  if (axis.kind === "no-axis") return null;
  if (axis.today < axis.start || axis.today >= axis.end) return null;
  const totalDays = dayDiff(axis.start, axis.end);
  if (totalDays <= 0) return null;
  return clampPct((dayDiff(axis.start, axis.today) / totalDays) * 100);
}

// ── Component ─────────────────────────────────────────────

const STYLES = `
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif; margin: 0; padding: 0; color: #222; background: #fafafa; }
  .gantt { max-width: 1400px; margin: 24px auto; padding: 20px 24px; background: #fff; border: 1px solid #e3e3e3; border-radius: 6px; }
  .header { border-bottom: 1px solid #e3e3e3; padding-bottom: 12px; margin-bottom: 16px; }
  .header h1 { margin: 0 0 4px 0; font-size: 20px; font-weight: 600; }
  .header .meta { font-size: 12px; color: #777; }
  .header .legend { font-size: 11px; color: #666; margin-top: 8px; }
  .legend-glyph { display: inline-block; width: 18px; }
  .counter { background: #fcfcfc; border: 1px solid #ececec; border-radius: 4px; padding: 10px 12px; margin: 12px 0; }
  .counter-headline { font-size: 14px; font-weight: 600; margin: 0 0 6px 0; color: #333; }
  .counter-breakdown { margin: 6px 0 0 0; padding-left: 18px; font-size: 12px; color: #555; }
  .counter-breakdown li { margin: 2px 0; }
  .issue-code { background: #f0f0f0; padding: 1px 5px; border-radius: 3px; font-family: ui-monospace, monospace; font-size: 11px; }
  .issue-count { color: #888; font-size: 11px; }
  .alerts { background: #fff8f0; border: 1px solid #ffd9a8; border-left: 4px solid #d97706; border-radius: 4px; padding: 10px 12px; margin: 12px 0; }
  .alerts h3 { font-size: 12px; font-weight: 600; margin: 0 0 6px 0; color: #92400e; text-transform: uppercase; letter-spacing: 0.5px; }
  .alerts ul { margin: 0; padding-left: 18px; font-size: 12px; }
  .alerts li { margin: 2px 0; color: #5a3a0c; }
  .body { margin-top: 16px; }
  .axis-row { display: grid; grid-template-columns: 240px 220px 130px 1fr; align-items: end; font-size: 11px; color: #888; padding: 4px 0; border-bottom: 1px solid #ddd; }
  .axis-spacer { grid-column: span 3; }
  .axis-cells { position: relative; height: 18px; }
  .axis-cell { position: absolute; top: 0; bottom: 0; padding-left: 4px; border-left: 1px solid #ececec; font-size: 10px; }
  .row { display: grid; grid-template-columns: 240px 220px 130px 1fr; align-items: center; padding: 6px 0; border-bottom: 1px solid #f3f3f3; min-height: 28px; }
  .row .title { font-size: 13px; font-weight: 500; padding-right: 8px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .row .meta { font-size: 11px; color: #666; padding-right: 8px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .row .dates { font-size: 11px; color: #555; font-variant-numeric: tabular-nums; padding-right: 8px; }
  .row .dates.bad { color: #c0392b; font-weight: 600; }
  .timeline { position: relative; height: 22px; background: #fafafa; border-radius: 3px; }
  .bar { position: absolute; top: 4px; bottom: 4px; background: #3b82f6; border-radius: 2px; }
  .row.completed .bar { background: #94a3b8; opacity: 0.55; }
  .row.completed .title, .row.completed .meta, .row.completed .dates { opacity: 0.55; }
  .row.canceled .bar { background: #94a3b8; opacity: 0.45; }
  .row.canceled .title, .row.canceled .meta, .row.canceled .dates { text-decoration: line-through; opacity: 0.55; }
  .milestone { position: absolute; top: 4px; width: 14px; height: 14px; transform: translateX(-7px) rotate(45deg); background: #6366f1; }
  .row.completed .milestone { background: #94a3b8; opacity: 0.55; }
  .today-line { position: absolute; top: 0; bottom: 0; width: 1px; background: #ef4444; pointer-events: none; }
  .today-label { position: absolute; top: -14px; transform: translateX(-50%); font-size: 9px; color: #ef4444; white-space: nowrap; }
  .alert-badge { color: #d97706; font-weight: 600; margin-left: 6px; font-size: 11px; }
  .sub-row { background: #fff8f0; border-left: 3px solid #d97706; padding: 4px 12px 4px 248px; font-size: 11px; color: #5a3a0c; }
  .sub-row .alert-line { display: block; margin: 1px 0; }
  .sub-row code { background: rgba(217, 119, 6, 0.08); padding: 0 4px; border-radius: 2px; font-family: ui-monospace, monospace; font-size: 10px; }
  .no-axis-note { font-size: 11px; color: #888; padding: 10px; text-align: center; background: #fafafa; border-radius: 4px; margin: 8px 0; }
`;

function metaLine(row: AnnotatedRow): string {
  const ownerPart = row.owner ? `O: ${row.owner}` : "";
  const resourcesPart = row.resources ?? "";
  return [ownerPart, resourcesPart].filter(Boolean).join(" · ");
}

function rowClass(row: AnnotatedRow): string {
  const classes = ["row"];
  if (row.kind === "weekitem" || row.kind === "project") {
    if (row.status === "completed") classes.push("completed");
    if (row.status === "canceled") classes.push("canceled");
  }
  return classes.join(" ");
}

function inlineDateClass(row: AnnotatedRow): string {
  return row.inline.length > 0 ? "dates bad" : "dates";
}

function chartLabel(data: GanttData): string {
  return data.raw.kind === "wrapper" ? "Wrapper" : "L1";
}

function GanttTemplate({ data }: { data: GanttData }): JSX.Element {
  const { raw, rows, chartIssues, axis, headerRange, generatedAt, summary } = data;
  const todayPct = computeTodayPosition(axis);

  return (
    <html lang="en">
      <head>
        <meta charSet="utf-8" />
        <title>{`Gantt — ${raw.client.name}: ${raw.entity.name}`}</title>
        <style dangerouslySetInnerHTML={{ __html: STYLES }} />
      </head>
      <body>
        <div className="gantt">
          {/* 1. Header */}
          <header className="header">
            <h1>
              {raw.client.name}: {raw.entity.name}{" "}
              <span style={{ fontSize: "12px", fontWeight: 400, color: "#888" }}>
                ({chartLabel(data)})
              </span>
            </h1>
            <div className="meta">
              <span>{headerRange}</span>
              <span> · Generated {generatedAt}</span>
            </div>
            <div className="legend">
              <span className="legend-glyph">▬</span> active bar ·
              <span className="legend-glyph"> ◆</span> milestone ·
              <span className="legend-glyph"> ⚠</span> alert ·
              <span> faded = completed · </span>
              <span style={{ textDecoration: "line-through" }}>strikethrough</span> = canceled
            </div>
          </header>

          {/* 2 + 3. Counter line + breakdown */}
          {formatCounterMarkup(summary)}

          {/* 4. Chart-level alerts (also shown again here in full) */}
          {chartIssues.length > 0 && (
            <section className="alerts">
              <h3>Chart-level issues ({chartIssues.length})</h3>
              <ul>
                {chartIssues.map((issue, idx) => (
                  <li key={`${issue.code}-${idx}`}>
                    <code>{issue.code}</code> — {issue.message}
                  </li>
                ))}
              </ul>
            </section>
          )}

          {/* 5. Body */}
          <section className="body">
            {axis.kind === "no-axis" && (
              <div className="no-axis-note">
                No dates available — body rendered without a timeline.
              </div>
            )}
            {axis.kind !== "no-axis" && (
              <div className="axis-row">
                <div className="axis-spacer" />
                <div className="axis-cells">
                  {axis.columns.map((col) => {
                    const colLeft = clampPct(
                      (dayDiff(axis.start, col.date) /
                        dayDiff(axis.start, axis.end)) *
                        100,
                    );
                    return (
                      <div
                        key={col.date}
                        className="axis-cell"
                        style={{ left: `${colLeft}%` }}
                      >
                        {col.label}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {rows.map((row) => (
              <RowBlock key={row.id} row={row} axis={axis} todayPct={todayPct} />
            ))}
          </section>
        </div>
      </body>
    </html>
  );
}

function RowBlock({
  row,
  axis,
  todayPct,
}: {
  row: AnnotatedRow;
  axis: AxisParams;
  todayPct: number | null;
}): JSX.Element {
  const geom = computeBarGeometry(row, axis);
  const showTodayLine = todayPct !== null && axis.kind !== "no-axis";
  return (
    <>
      <div className={rowClass(row)} data-row-kind={row.kind}>
        <div className="title">
          {row.title}
          {row.subRow.length > 0 && <span className="alert-badge">⚠</span>}
        </div>
        <div className="meta">{metaLine(row)}</div>
        <div className={inlineDateClass(row)}>{formatDateRange(row.startDate, row.endDate)}</div>
        <div className="timeline">
          {axis.kind !== "no-axis" && showTodayLine && (
            <div className="today-line" style={{ left: `${todayPct}%` }} />
          )}
          {geom.kind === "bar" && (
            <div className="bar" style={{ left: `${geom.left}%`, width: `${geom.width}%` }} />
          )}
          {geom.kind === "milestone" && (
            <div className="milestone" style={{ left: `${geom.left}%` }} />
          )}
        </div>
      </div>
      {row.subRow.length > 0 && (
        <div className="sub-row">
          {row.subRow.map((issue: Issue, idx: number) => (
            <span key={`${issue.code}-${idx}`} className="alert-line">
              <code>{issue.code}</code> — {issue.message}
            </span>
          ))}
        </div>
      )}
    </>
  );
}

export { GanttTemplate };

/** Render the full HTML document for one Gantt. */
export function renderGantt(data: GanttData): string {
  return "<!doctype html>" + renderToStaticMarkup(<GanttTemplate data={data} />);
}

import { describe, expect, it } from "vitest";
import {
  computeBarGeometry,
  computeTodayPosition,
  renderGantt,
} from "./GanttTemplate";
import type {
  AnnotatedRow,
  AxisParams,
  ClientRow,
  GanttData,
  ProjectRow,
  RawData,
} from "./types";

const NOW = new Date("2026-04-28T00:00:00Z");

function makeClient(): ClientRow {
  return {
    id: "c1",
    name: "Test Client",
    slug: "test-client",
    nicknames: null,
    contractValue: null,
    contractTerm: null,
    contractStatus: null,
    team: null,
    clientContacts: null,
    createdAt: NOW,
    updatedAt: NOW,
  };
}

function makeProject(overrides: Partial<ProjectRow> = {}): ProjectRow {
  return {
    id: "p1",
    clientId: "c1",
    name: "Test Project",
    status: null,
    category: null,
    owner: null,
    resources: null,
    waitingOn: null,
    dueDate: null,
    startDate: null,
    endDate: null,
    contractStart: null,
    contractEnd: null,
    engagementType: null,
    parentProjectId: null,
    notes: null,
    staleDays: null,
    sortOrder: 0,
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

function makeRow(overrides: Partial<AnnotatedRow> = {}): AnnotatedRow {
  return {
    kind: "weekitem",
    id: "w1",
    title: "Item",
    owner: null,
    resources: null,
    startDate: null,
    endDate: null,
    status: null,
    category: null,
    weekOf: null,
    inline: [],
    subRow: [],
    ...overrides,
  } as AnnotatedRow;
}

const weeklyAxis: AxisParams = {
  kind: "weekly",
  start: "2026-04-13",
  end: "2026-05-25",
  today: "2026-04-28",
  columns: [
    { date: "2026-04-13", label: "4/13" },
    { date: "2026-04-20", label: "4/20" },
    { date: "2026-04-27", label: "4/27" },
    { date: "2026-05-04", label: "5/4" },
    { date: "2026-05-11", label: "5/11" },
    { date: "2026-05-18", label: "5/18" },
  ],
};

// ── Geometry ─────────────────────────────────────────────

describe("computeBarGeometry", () => {
  it("returns bar geometry with positive left + width for a normal range", () => {
    const row = makeRow({ startDate: "2026-04-20", endDate: "2026-04-26" });
    const geom = computeBarGeometry(row, weeklyAxis);
    expect(geom.kind).toBe("bar");
    if (geom.kind === "bar") {
      expect(geom.left).toBeGreaterThan(0);
      expect(geom.left).toBeLessThan(50);
      expect(geom.width).toBeGreaterThan(0);
    }
  });

  it("returns milestone geometry when start === end", () => {
    const row = makeRow({ startDate: "2026-05-04", endDate: "2026-05-04" });
    const geom = computeBarGeometry(row, weeklyAxis);
    expect(geom.kind).toBe("milestone");
  });

  it("returns none when both dates are null", () => {
    const row = makeRow({ startDate: null, endDate: null });
    expect(computeBarGeometry(row, weeklyAxis).kind).toBe("none");
  });

  it("returns none when only one date is set", () => {
    const row = makeRow({ startDate: "2026-04-20", endDate: null });
    expect(computeBarGeometry(row, weeklyAxis).kind).toBe("none");
  });

  it("returns none when end < start (bad pair)", () => {
    const row = makeRow({ startDate: "2026-05-10", endDate: "2026-04-20" });
    expect(computeBarGeometry(row, weeklyAxis).kind).toBe("none");
  });

  it("returns none when axis has no-axis kind", () => {
    const row = makeRow({ startDate: "2026-04-20", endDate: "2026-04-26" });
    const geom = computeBarGeometry(row, { kind: "no-axis", today: "2026-04-28" });
    expect(geom.kind).toBe("none");
  });
});

describe("computeTodayPosition", () => {
  it("returns a percent within 0-100 for an in-range today", () => {
    const pct = computeTodayPosition(weeklyAxis);
    expect(pct).not.toBeNull();
    expect(pct!).toBeGreaterThan(0);
    expect(pct!).toBeLessThan(100);
  });

  it("returns null when today is before axis start", () => {
    const before: AxisParams = { ...weeklyAxis, today: "2026-01-01" };
    expect(computeTodayPosition(before)).toBeNull();
  });

  it("returns null for no-axis", () => {
    expect(
      computeTodayPosition({ kind: "no-axis", today: "2026-04-28" }),
    ).toBeNull();
  });
});

// ── renderGantt: structural assertions on output HTML ─────

function makeGanttData(overrides: Partial<GanttData> = {}): GanttData {
  const entity = makeProject({
    id: "p-l1",
    name: "Sample L1",
    startDate: "2026-04-15",
    endDate: "2026-05-15",
  });
  const client = makeClient();
  const raw: RawData = { kind: "l1", entity, client, children: [] };
  return {
    raw,
    rows: [],
    chartIssues: [],
    axis: weeklyAxis,
    headerRange: "4/15 – 5/15",
    generatedAt: "2026-04-28",
    summary: { rowsWithGaps: 0, totalRows: 0, chartIssueCount: 0, byCode: {} },
    ...overrides,
  };
}

describe("renderGantt", () => {
  it("includes the doctype and html structure", () => {
    const html = renderGantt(makeGanttData());
    expect(html.startsWith("<!doctype html>")).toBe(true);
    expect(html).toContain("<html");
    expect(html).toContain("</html>");
  });

  it("includes the project name and header range", () => {
    const html = renderGantt(makeGanttData());
    expect(html).toContain("Test Client");
    expect(html).toContain("Sample L1");
    expect(html).toContain("4/15 – 5/15");
    expect(html).toContain("Generated 2026-04-28");
  });

  it("renders the legend with all 5 elements", () => {
    const html = renderGantt(makeGanttData());
    expect(html).toContain("active bar");
    expect(html).toContain("milestone");
    expect(html).toContain("alert");
    expect(html).toContain("faded = completed");
    expect(html).toContain("= canceled");
  });

  it("renders the counter headline with split clauses", () => {
    const data = makeGanttData({
      rows: [
        makeRow({ id: "w1", title: "A", inline: [{ code: "wi-only-end-null", message: "end null" }] }),
        makeRow({ id: "w2", title: "B" }),
      ],
      chartIssues: [{ code: "l1-null-engagement-type", message: "null" }],
      summary: {
        rowsWithGaps: 1,
        totalRows: 2,
        chartIssueCount: 1,
        byCode: {
          "wi-only-end-null": [{ id: "w1", title: "A" }],
          "l1-null-engagement-type": [{ id: "p-l1", title: "Sample L1" }],
        },
      },
    });
    const html = renderGantt(data);
    expect(html).toContain("1 of 2 rows have data gaps + 1 chart-level issue");
  });

  it("renders the chart-level alerts section in addition to the counter", () => {
    const data = makeGanttData({
      chartIssues: [
        { code: "l1-null-engagement-type", message: "engagementType is null." },
      ],
      summary: {
        rowsWithGaps: 0,
        totalRows: 0,
        chartIssueCount: 1,
        byCode: {
          "l1-null-engagement-type": [{ id: "p-l1", title: "Sample L1" }],
        },
      },
    });
    const html = renderGantt(data);
    // Counter breakdown
    expect(html).toContain("counter-breakdown");
    expect(html).toContain("l1-null-engagement-type");
    // Alert section (operator wants alerts in BOTH places)
    expect(html).toContain("Chart-level issues");
    expect(html).toContain("engagementType is null.");
  });

  it("renders rows with formatted inline date range", () => {
    const data = makeGanttData({
      rows: [makeRow({ id: "w1", title: "Concept", startDate: "2026-04-30", endDate: null })],
    });
    const html = renderGantt(data);
    expect(html).toContain("Concept");
    expect(html).toContain("4/30 – null");
  });

  it("renders a milestone diamond when start === end", () => {
    const data = makeGanttData({
      rows: [
        makeRow({
          id: "w1",
          title: "Milestone",
          startDate: "2026-05-04",
          endDate: "2026-05-04",
        }),
      ],
    });
    const html = renderGantt(data);
    expect(html).toContain('class="milestone"');
  });

  it("does not render a bar element when both dates null", () => {
    const data = makeGanttData({
      rows: [makeRow({ id: "w1", title: "NoDates", startDate: null, endDate: null })],
    });
    const html = renderGantt(data);
    expect(html).not.toContain('class="bar"');
    // Inline shows the literal null/null
    expect(html).toContain("null – null");
  });

  it("renders a sub-row only when subRow issues are present", () => {
    const without = renderGantt(
      makeGanttData({ rows: [makeRow({ id: "a", title: "A" })] }),
    );
    expect(without).not.toContain("sub-row");

    const withSub = renderGantt(
      makeGanttData({
        rows: [
          makeRow({
            id: "b",
            title: "B",
            subRow: [{ code: "wi-overdue", message: "overdue" }],
          }),
        ],
      }),
    );
    expect(withSub).toContain('class="sub-row"');
    expect(withSub).toContain("wi-overdue");
  });

  it("renders the today line when axis has dates", () => {
    const html = renderGantt(makeGanttData());
    expect(html).toContain("today-line");
  });

  it("renders the no-axis note when axis kind is no-axis", () => {
    const data = makeGanttData({
      axis: { kind: "no-axis", today: "2026-04-28" },
    });
    const html = renderGantt(data);
    expect(html).toContain("No dates available");
    expect(html).not.toContain("today-line");
  });

  it("applies the completed class to rows with status=completed", () => {
    const data = makeGanttData({
      rows: [
        makeRow({
          id: "c",
          title: "Done",
          status: "completed",
          startDate: "2026-04-20",
          endDate: "2026-04-26",
        }),
      ],
    });
    const html = renderGantt(data);
    expect(html).toContain("row completed");
  });

  it("applies the canceled class to rows with status=canceled", () => {
    const data = makeGanttData({
      rows: [
        makeRow({
          id: "x",
          title: "Cancel",
          status: "canceled",
          startDate: "2026-04-20",
          endDate: "2026-04-26",
        }),
      ],
    });
    const html = renderGantt(data);
    expect(html).toContain("row canceled");
  });

  it("emits an alert badge ⚠ on rows that have sub-row issues", () => {
    const data = makeGanttData({
      rows: [
        makeRow({
          id: "alert",
          title: "Has alert",
          subRow: [{ code: "wi-overdue", message: "overdue" }],
        }),
      ],
    });
    const html = renderGantt(data);
    expect(html).toContain("alert-badge");
    expect(html).toContain("⚠");
  });
});

