import { createRunwayDb } from "./lib/run-script";
import { resolveProject } from "./lib/gantt/resolve-entity";
import { extractData } from "./lib/gantt/extract-data";
import { transformRows, computeAxis, formatDateRange } from "./lib/gantt/transform-rows";
import { detectAllIssues } from "./lib/gantt/detect-issues";
import { summarize } from "./lib/gantt/counter";
import { renderGantt } from "./lib/gantt/GanttTemplate";
import type { GanttData } from "./lib/gantt/types";
import { eq } from "drizzle-orm";
import { clients } from "@/lib/db/runway-schema";
import { writeFileSync } from "fs";
import { homedir } from "os";
import { join } from "path";

async function main() {
  const { db } = createRunwayDb();
  const today = new Date("2026-04-28T00:00:00Z");
  const generatedAt = today.toISOString().slice(0, 10);

  for (const input of ["Website Build", "1H Convergix Retainer", "Social Content Trial", "AG1 PRO Content"]) {
    const r = await resolveProject(db, input);
    if (!r.ok) continue;
    const [client] = await db.select().from(clients).where(eq(clients.id, r.subject.project.clientId));
    const data = await extractData(db, r.subject, client);
    const baseRows = transformRows(data);
    const axis = computeAxis(data, baseRows, today);
    const det = detectAllIssues(data, baseRows, today);
    const summary = summarize({ rows: det.rows, chartIssues: det.chartIssues, entity: data.entity });
    const headerRange = formatDateRange(data.entity.startDate, data.entity.endDate);
    const ganttData: GanttData = {
      raw: data,
      rows: det.rows,
      chartIssues: det.chartIssues,
      axis,
      headerRange,
      generatedAt,
      summary,
    };
    const html = renderGantt(ganttData);
    const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
    const filename = `${slug(client.name)}-${slug(data.entity.name)}-${generatedAt}.html`;
    const out = join(homedir(), "runway-gantts", filename);
    writeFileSync(out, html, "utf-8");
    console.log(`wrote ${out} (${html.length} bytes)`);
  }
}

main().catch((err) => { console.error(err); process.exit(1); });
