/**
 * Static HTML template for a single Gantt render. Rendered server-side via
 * `renderToStaticMarkup`. Self-contained: inline `<style>` block, no JS.
 *
 * Render order (operator-locked):
 *   1. Header (name + raw date range + generated stamp + legend)
 *   2. Data Integrity panel (severity rollup + grouped issues + per-child
 *      rollup for wrapper view)
 *   3. Gantt body (table-style row + sub-row alerts)
 *
 * The panel replaces the older "counter + alerts" duo. Chart-level issues
 * render with full messages; row-level issues collapse to code + count +
 * affected entity titles (their full messages already render on the row's
 * sub-row in the body below).
 */

import * as React from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { formatHeadline, formatSeverityLine } from "./counter";
import type {
  AnnotatedRow,
  AxisParams,
  ChildRollupEntry,
  GanttData,
  Issue,
  Severity,
  Summary,
} from "./types";

function numericDate(iso: string): string {
  const m = iso.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return iso;
  return `${parseInt(m[2], 10)}/${parseInt(m[3], 10)}`;
}

function DateOrNull({ value }: { value: string | null }): JSX.Element {
  if (value === null) return <span className="null">null</span>;
  return <span>{numericDate(value)}</span>;
}

// ── Bar / marker geometry ─────────────────────────────────

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function parseISO(s: string): Date {
  return new Date(`${s}T00:00:00Z`);
}

function dayDiff(from: string, to: string): number {
  return Math.round((parseISO(to).getTime() - parseISO(from).getTime()) / MS_PER_DAY);
}

function clampPct(n: number): number {
  if (Number.isNaN(n)) return 0;
  return Math.max(0, Math.min(100, n));
}

type BarGeometry =
  | { kind: "bar"; left: number; width: number }
  | { kind: "milestone"; left: number }
  | { kind: "none" };

export function computeBarGeometry(row: AnnotatedRow, axis: AxisParams): BarGeometry {
  if (axis.kind === "no-axis") return { kind: "none" };
  if (row.startDate === null || row.endDate === null) return { kind: "none" };
  if (row.endDate < row.startDate) return { kind: "none" };
  const totalDays = dayDiff(axis.start, axis.end);
  if (totalDays <= 0) return { kind: "none" };
  if (row.startDate === row.endDate) {
    const left = clampPct((dayDiff(axis.start, row.startDate) / totalDays) * 100);
    return { kind: "milestone", left };
  }
  const left = clampPct((dayDiff(axis.start, row.startDate) / totalDays) * 100);
  const widthDays = dayDiff(row.startDate, row.endDate) + 1;
  const width = clampPct((widthDays / totalDays) * 100);
  return { kind: "bar", left, width };
}

export function computeTodayPosition(axis: AxisParams): number | null {
  if (axis.kind === "no-axis") return null;
  if (axis.today < axis.start || axis.today >= axis.end) return null;
  const totalDays = dayDiff(axis.start, axis.end);
  if (totalDays <= 0) return null;
  return clampPct((dayDiff(axis.start, axis.today) / totalDays) * 100);
}

// ── Component ─────────────────────────────────────────────

const STYLES = `
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif; margin: 0; padding: 0; color: #222; background: #fafafa; }
  .gantt { max-width: 1400px; margin: 24px auto; padding: 20px 24px; background: #fff; border: 1px solid #e3e3e3; border-radius: 6px; }
  .header { border-bottom: 1px solid #e3e3e3; padding-bottom: 12px; margin-bottom: 16px; }
  .header h1 { margin: 0 0 4px 0; font-size: 20px; font-weight: 600; }
  .header .meta { font-size: 12px; color: #777; }
  .header .legend { font-size: 11px; color: #666; margin-top: 8px; }
  .legend-glyph { display: inline-block; width: 18px; }

  /* Data Integrity panel */
  .panel { border: 1px solid #e3e3e3; border-radius: 6px; margin: 12px 0 18px 0; background: #fff; }
  .panel-head { padding: 12px 14px; border-bottom: 1px solid #ececec; }
  .panel-head h2 { margin: 0 0 4px 0; font-size: 14px; font-weight: 600; color: #333; text-transform: uppercase; letter-spacing: 0.5px; }
  .panel-head .severity-line { font-size: 13px; font-weight: 600; }
  .panel-head .severity-line.critical { color: #b91c1c; }
  .panel-head .severity-line.warn { color: #b45309; }
  .panel-head .severity-line.clean { color: #15803d; }
  .panel-head .headline-sub { font-size: 12px; color: #666; margin-top: 4px; }

  .panel-section { padding: 10px 14px; border-top: 1px solid #f3f3f3; }
  .panel-section h3 { margin: 0 0 8px 0; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; }
  .panel-section.critical { background: #fef2f2; border-left: 4px solid #b91c1c; }
  .panel-section.critical h3 { color: #991b1b; }
  .panel-section.warn { background: #fffbeb; border-left: 4px solid #d97706; }
  .panel-section.warn h3 { color: #92400e; }
  .panel-section.info { background: #f8fafc; border-left: 4px solid #64748b; }
  .panel-section.info h3 { color: #475569; }
  .panel-section ul { margin: 0; padding-left: 18px; font-size: 12px; }
  .panel-section li { margin: 3px 0; }
  .panel-section code { background: rgba(0,0,0,0.05); padding: 1px 5px; border-radius: 3px; font-family: ui-monospace, monospace; font-size: 11px; }
  .panel-section .issue-message { color: #333; }
  .panel-section .issue-refs { color: #555; }
  .panel-section .issue-count { color: #888; }

  /* Per-child rollup */
  .panel-rollup { padding: 10px 14px; border-top: 1px solid #f3f3f3; }
  .panel-rollup h3 { margin: 0 0 8px 0; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; color: #475569; }
  .panel-rollup table { width: 100%; border-collapse: collapse; font-size: 12px; }
  .panel-rollup td { padding: 3px 8px 3px 0; vertical-align: top; }
  .panel-rollup td.title { font-weight: 500; }
  .panel-rollup td.tally { font-variant-numeric: tabular-nums; white-space: nowrap; }
  .panel-rollup .tally-critical { color: #b91c1c; font-weight: 600; }
  .panel-rollup .tally-warn { color: #b45309; }
  .panel-rollup .tally-info { color: #64748b; }
  .panel-rollup .tally-clean { color: #15803d; }

  /* Body */
  .body { margin-top: 16px; }
  .axis-row { display: grid; grid-template-columns: 340px 200px 130px 1fr; align-items: end; font-size: 11px; color: #888; padding: 4px 0; border-bottom: 1px solid #ddd; }
  .axis-spacer { grid-column: span 3; }
  .axis-cells { position: relative; height: 18px; }
  .axis-cell { position: absolute; top: 0; bottom: 0; padding-left: 4px; border-left: 1px solid #ececec; font-size: 10px; }
  .row { display: grid; grid-template-columns: 340px 200px 130px 1fr; align-items: center; padding: 6px 0; border-bottom: 1px solid #f3f3f3; min-height: 28px; }
  .row .title { font-size: 13px; font-weight: 500; padding-right: 8px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .row .meta { font-size: 11px; color: #666; padding-right: 8px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .row .dates { font-size: 11px; color: #555; font-variant-numeric: tabular-nums; padding-right: 8px; }
  .row .dates.bad { color: #c0392b; font-weight: 600; }
  .row .dates .null { color: #c0392b; font-weight: 600; }
  .timeline { position: relative; height: 22px; background: #fafafa; border-radius: 3px; }
  .bar { position: absolute; top: 4px; bottom: 4px; background: #3b82f6; border-radius: 2px; }
  .row.completed .bar { background: #94a3b8; opacity: 0.55; }
  .row.completed .title, .row.completed .meta, .row.completed .dates { opacity: 0.55; }
  .row.canceled .bar { background: #94a3b8; opacity: 0.45; }
  .row.canceled .title, .row.canceled .meta, .row.canceled .dates { text-decoration: line-through; opacity: 0.55; }
  .milestone { position: absolute; top: 4px; width: 14px; height: 14px; transform: translateX(-7px) rotate(45deg); background: #6366f1; }
  .row.completed .milestone { background: #94a3b8; opacity: 0.55; }
  .today-line { position: absolute; top: 0; bottom: 0; width: 1px; background: #ef4444; pointer-events: none; }
  .today-label { position: absolute; top: -14px; transform: translateX(-50%); font-size: 9px; color: #ef4444; white-space: nowrap; }
  .row .alert-badge.critical { color: #b91c1c; }
  .row .alert-badge.warn { color: #d97706; }
  .row .alert-badge.info { color: #64748b; }
  .alert-badge { font-weight: 600; margin-left: 6px; font-size: 11px; }
  .sub-row { padding: 4px 12px 4px 348px; font-size: 11px; }
  .sub-row.critical { background: #fef2f2; border-left: 3px solid #b91c1c; color: #7f1d1d; }
  .sub-row.warn { background: #fffbeb; border-left: 3px solid #d97706; color: #5a3a0c; }
  .sub-row.info { background: #f8fafc; border-left: 3px solid #64748b; color: #334155; }
  .sub-row .alert-line { display: block; margin: 1px 0; }
  .sub-row code { background: rgba(0,0,0,0.06); padding: 0 4px; border-radius: 2px; font-family: ui-monospace, monospace; font-size: 10px; }
  .no-axis-note { font-size: 11px; color: #888; padding: 10px; text-align: center; background: #fafafa; border-radius: 4px; margin: 8px 0; }
`;

function metaLine(row: AnnotatedRow): string {
  const ownerPart = row.owner ? `O: ${row.owner}` : "";
  const resourcesPart = row.resources ?? "";
  return [ownerPart, resourcesPart].filter(Boolean).join(" · ");
}

function rowClass(row: AnnotatedRow): string {
  const classes = ["row"];
  if (row.kind === "weekitem" || row.kind === "project") {
    if (row.status === "completed") classes.push("completed");
    if (row.status === "canceled") classes.push("canceled");
  }
  return classes.join(" ");
}

function inlineDateClass(row: AnnotatedRow): string {
  return row.inline.length > 0 ? "dates bad" : "dates";
}

function chartLabel(data: GanttData): string {
  return data.raw.kind === "wrapper" ? "Wrapper" : "L1";
}

/** The most-severe severity present on a row, for badge coloring. */
function highestSeverity(issues: Issue[]): Severity | null {
  if (issues.some((i) => i.severity === "critical")) return "critical";
  if (issues.some((i) => i.severity === "warn")) return "warn";
  if (issues.some((i) => i.severity === "info")) return "info";
  return null;
}

// ── Data Integrity panel ─────────────────────────────────

const SEVERITY_ORDER: Severity[] = ["critical", "warn", "info"];

type PanelEntry =
  | { kind: "chart"; issue: Issue }
  | { kind: "row-group"; code: string; severity: Severity; refs: { id: string; title: string }[] };

function buildPanelEntries(summary: Summary): Record<Severity, PanelEntry[]> {
  const buckets: Record<Severity, PanelEntry[]> = { critical: [], warn: [], info: [] };

  for (const ci of summary.chartIssues) {
    buckets[ci.severity].push({ kind: "chart", issue: ci });
  }
  // Row-level: group by code, look up severity from codeSeverity (which
  // covers both chart and row codes — chart codes are skipped because
  // they're already represented above).
  const chartCodes = new Set(summary.chartIssues.map((i) => i.code));
  const rowCodes = Object.keys(summary.byCode)
    .filter((c) => !chartCodes.has(c as Issue["code"]))
    .sort();
  for (const code of rowCodes) {
    const sev = summary.codeSeverity[code] ?? "warn";
    buckets[sev].push({
      kind: "row-group",
      code,
      severity: sev,
      refs: summary.byCode[code],
    });
  }
  return buckets;
}

function PanelEntryItem({ entry }: { entry: PanelEntry }): JSX.Element {
  if (entry.kind === "chart") {
    return (
      <li>
        <code>{entry.issue.code}</code>{" "}
        <span className="issue-message">— {entry.issue.message}</span>
      </li>
    );
  }
  const titles = entry.refs.map((r) => r.title).join(", ");
  return (
    <li>
      <code>{entry.code}</code>{" "}
      <span className="issue-count">({entry.refs.length})</span>{" "}
      <span className="issue-refs">— {titles}</span>
    </li>
  );
}

function severityClassForLine(s: Summary["severity"]): string {
  if (s.critical > 0) return "severity-line critical";
  if (s.warn > 0 || s.info > 0) return "severity-line warn";
  return "severity-line clean";
}

function PerChildRollup({ entries }: { entries: ChildRollupEntry[] }): JSX.Element | null {
  if (entries.length === 0) return null;
  return (
    <div className="panel-rollup">
      <h3>Per-child rollup</h3>
      <table>
        <tbody>
          {entries.map((e) => {
            const isClean = e.critical + e.warn + e.info === 0;
            return (
              <tr key={e.id}>
                <td className="title">{e.title}</td>
                <td className="tally">
                  {isClean ? (
                    <span className="tally-clean">clean</span>
                  ) : (
                    <>
                      {e.critical > 0 && (
                        <span className="tally-critical">{e.critical} critical</span>
                      )}
                      {e.critical > 0 && (e.warn > 0 || e.info > 0) && " · "}
                      {e.warn > 0 && <span className="tally-warn">{e.warn} warn</span>}
                      {e.warn > 0 && e.info > 0 && " · "}
                      {e.info > 0 && <span className="tally-info">{e.info} info</span>}
                    </>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function DataIntegrityPanel({
  summary,
  isWrapper,
}: {
  summary: Summary;
  isWrapper: boolean;
}): JSX.Element {
  const buckets = buildPanelEntries(summary);
  return (
    <section className="panel">
      <div className="panel-head">
        <h2>Data Integrity</h2>
        <div className={severityClassForLine(summary.severity)}>
          {formatSeverityLine(summary.severity)}
        </div>
        <div className="headline-sub">{formatHeadline(summary)}</div>
      </div>
      {SEVERITY_ORDER.map((sev) =>
        buckets[sev].length === 0 ? null : (
          <div key={sev} className={`panel-section ${sev}`}>
            <h3>
              {sev} ({buckets[sev].length})
            </h3>
            <ul>
              {buckets[sev].map((entry, i) => (
                <PanelEntryItem
                  key={`${entry.kind === "chart" ? entry.issue.code : entry.code}-${i}`}
                  entry={entry}
                />
              ))}
            </ul>
          </div>
        ),
      )}
      {isWrapper && summary.childRollup && <PerChildRollup entries={summary.childRollup} />}
    </section>
  );
}

// ── Page ─────────────────────────────────────────────────

function GanttTemplate({ data }: { data: GanttData }): JSX.Element {
  const { raw, rows, axis, headerRange, generatedAt, summary } = data;
  const todayPct = computeTodayPosition(axis);

  return (
    <html lang="en">
      {/* eslint-disable-next-line @next/next/no-head-element -- standalone HTML doc, not a Next.js page */}
      <head>
        <meta charSet="utf-8" />
        <title>{`Gantt — ${raw.client.name}: ${raw.entity.name}`}</title>
        <style dangerouslySetInnerHTML={{ __html: STYLES }} />
      </head>
      <body>
        <div className="gantt">
          <header className="header">
            <h1>
              {raw.client.name}: {raw.entity.name}{" "}
              <span style={{ fontSize: "12px", fontWeight: 400, color: "#888" }}>
                ({chartLabel(data)})
              </span>
            </h1>
            <div className="meta">
              <span>{headerRange}</span>
              <span> · Generated {generatedAt}</span>
            </div>
            <div className="legend">
              <span className="legend-glyph">▬</span> active bar ·
              <span className="legend-glyph"> ◆</span> milestone ·
              <span className="legend-glyph"> ⚠</span> alert ·
              <span> faded = completed · </span>
              <span style={{ textDecoration: "line-through" }}>strikethrough</span> = canceled
            </div>
          </header>

          <DataIntegrityPanel summary={summary} isWrapper={raw.kind === "wrapper"} />

          <section className="body">
            {axis.kind === "no-axis" && (
              <div className="no-axis-note">
                No dates available — body rendered without a timeline.
              </div>
            )}
            {axis.kind !== "no-axis" && (
              <div className="axis-row">
                <div className="axis-spacer" />
                <div className="axis-cells">
                  {axis.columns.map((col) => {
                    const colLeft = clampPct(
                      (dayDiff(axis.start, col.date) / dayDiff(axis.start, axis.end)) * 100,
                    );
                    return (
                      <div
                        key={col.date}
                        className="axis-cell"
                        style={{ left: `${colLeft}%` }}
                      >
                        {col.label}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {rows.map((row) => (
              <RowBlock key={row.id} row={row} axis={axis} todayPct={todayPct} />
            ))}
          </section>
        </div>
      </body>
    </html>
  );
}

function RowBlock({
  row,
  axis,
  todayPct,
}: {
  row: AnnotatedRow;
  axis: AxisParams;
  todayPct: number | null;
}): JSX.Element {
  const geom = computeBarGeometry(row, axis);
  const showTodayLine = todayPct !== null && axis.kind !== "no-axis";
  const allRowIssues = [...row.inline, ...row.subRow];
  const rowSeverity = highestSeverity(allRowIssues);
  return (
    <>
      <div className={rowClass(row)} data-row-kind={row.kind}>
        <div className="title">
          {row.title}
          {row.subRow.length > 0 && rowSeverity && (
            <span className={`alert-badge ${rowSeverity}`}>⚠</span>
          )}
        </div>
        <div className="meta">{metaLine(row)}</div>
        <div className={inlineDateClass(row)}>
          <DateOrNull value={row.startDate} />
          <span> – </span>
          <DateOrNull value={row.endDate} />
        </div>
        <div className="timeline">
          {axis.kind !== "no-axis" && showTodayLine && (
            <div className="today-line" style={{ left: `${todayPct}%` }} />
          )}
          {geom.kind === "bar" && (
            <div className="bar" style={{ left: `${geom.left}%`, width: `${geom.width}%` }} />
          )}
          {geom.kind === "milestone" && (
            <div className="milestone" style={{ left: `${geom.left}%` }} />
          )}
        </div>
      </div>
      {row.subRow.length > 0 && (
        <div className={`sub-row ${highestSeverity(row.subRow) ?? "warn"}`}>
          {row.subRow.map((issue: Issue, idx: number) => (
            <span key={`${issue.code}-${idx}`} className="alert-line">
              <code>{issue.code}</code> — {issue.message}
            </span>
          ))}
        </div>
      )}
    </>
  );
}

export { GanttTemplate };

/** Render the full HTML document for one Gantt. */
export function renderGantt(data: GanttData): string {
  return "<!doctype html>" + renderToStaticMarkup(<GanttTemplate data={data} />);
}

import { describe, expect, it } from "vitest";
import { renderToStaticMarkup } from "react-dom/server";
import {
  formatCounterConsole,
  formatCounterMarkup,
  formatHeadline,
  formatSeverityLine,
  summarize,
} from "./counter";
import type {
  AnnotatedRow,
  Issue,
  IssueCode,
  ProjectRow,
  Severity,
  Summary,
} from "./types";

const NOW = new Date("2026-04-29T00:00:00Z");

function makeProject(overrides: Partial<ProjectRow> = {}): ProjectRow {
  return {
    id: "p1",
    clientId: "c1",
    name: "Subject",
    status: null,
    category: null,
    owner: null,
    resources: null,
    waitingOn: null,
    dueDate: null,
    startDate: null,
    endDate: null,
    contractStart: null,
    contractEnd: null,
    engagementType: null,
    parentProjectId: null,
    notes: null,
    staleDays: null,
    sortOrder: 0,
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

function makeRow(overrides: Partial<AnnotatedRow> = {}): AnnotatedRow {
  return {
    kind: "weekitem",
    id: "w1",
    title: "Item",
    owner: null,
    resources: null,
    startDate: null,
    endDate: null,
    status: null,
    category: null,
    weekOf: null,
    inline: [],
    subRow: [],
    ...overrides,
  } as AnnotatedRow;
}

function mkIssue(code: IssueCode, severity: Severity = "warn", message = "x"): Issue {
  return { code, message, severity };
}

const entity = makeProject({ id: "p-l1", name: "Sample L1" });

// ── summarize ────────────────────────────────────────────

describe("summarize", () => {
  it("returns zeros and an empty byCode for clean data", () => {
    const result = summarize({
      rows: [makeRow({ id: "a" }), makeRow({ id: "b" })],
      chartIssues: [],
      entity,
    });
    expect(result.rowsWithGaps).toBe(0);
    expect(result.totalRows).toBe(2);
    expect(result.chartIssueCount).toBe(0);
    expect(result.byCode).toEqual({});
    expect(result.severity).toEqual({ critical: 0, warn: 0, info: 0 });
    expect(result.chartIssues).toEqual([]);
  });

  it("counts a row exactly once even if it has multiple issues", () => {
    const result = summarize({
      rows: [
        makeRow({
          id: "a",
          inline: [mkIssue("wi-only-end-null", "warn")],
          subRow: [mkIssue("wi-overdue", "warn")],
        }),
      ],
      chartIssues: [],
      entity,
    });
    expect(result.rowsWithGaps).toBe(1);
    expect(result.totalRows).toBe(1);
    expect(result.severity).toEqual({ critical: 0, warn: 2, info: 0 });
  });

  it("aggregates row entities under each issue code", () => {
    const issue = mkIssue("wi-only-end-null", "warn");
    const result = summarize({
      rows: [
        makeRow({ id: "a", title: "First", inline: [issue] }),
        makeRow({ id: "b", title: "Second", inline: [issue] }),
        makeRow({ id: "c", title: "Third" }),
      ],
      chartIssues: [],
      entity,
    });
    expect(result.byCode["wi-only-end-null"]).toEqual([
      { id: "a", title: "First" },
      { id: "b", title: "Second" },
    ]);
  });

  it("attaches chart-level issues to byCode using the entity name as the ref", () => {
    const result = summarize({
      rows: [],
      chartIssues: [
        mkIssue("l1-null-engagement-type", "warn"),
        mkIssue("l1-null-engagement-type", "warn"),
      ],
      entity,
    });
    expect(result.chartIssueCount).toBe(2);
    expect(result.byCode["l1-null-engagement-type"]).toEqual([
      { id: "p-l1", title: "Sample L1" },
      { id: "p-l1", title: "Sample L1" },
    ]);
  });

  it("rolls severity counts across rows + chart issues", () => {
    const result = summarize({
      rows: [
        makeRow({
          id: "row",
          inline: [mkIssue("wi-end-before-start", "critical")],
          subRow: [mkIssue("wi-bare-resource-name", "info")],
        }),
      ],
      chartIssues: [
        mkIssue("wrapper-bad-engagement-type", "critical"),
        mkIssue("l1-null-dates", "warn"),
      ],
      entity,
    });
    expect(result.severity).toEqual({ critical: 2, warn: 1, info: 1 });
  });

  it("populates childRollup with per-row severity tallies", () => {
    const result = summarize({
      rows: [
        makeRow({
          id: "a",
          title: "Alpha",
          inline: [mkIssue("wi-end-before-start", "critical")],
        }),
        makeRow({ id: "b", title: "Beta" }),
      ],
      chartIssues: [],
      entity,
    });
    expect(result.childRollup).toEqual([
      { id: "a", title: "Alpha", critical: 1, warn: 0, info: 0 },
      { id: "b", title: "Beta", critical: 0, warn: 0, info: 0 },
    ]);
  });

  it("populates codeSeverity from both row + chart sources", () => {
    const result = summarize({
      rows: [makeRow({ inline: [mkIssue("wi-end-before-start", "critical")] })],
      chartIssues: [mkIssue("wrapper-no-children", "critical")],
      entity,
    });
    expect(result.codeSeverity["wi-end-before-start"]).toBe("critical");
    expect(result.codeSeverity["wrapper-no-children"]).toBe("critical");
  });
});

// ── formatHeadline ───────────────────────────────────────

function makeSummary(overrides: Partial<Summary> = {}): Summary {
  return {
    rowsWithGaps: 0,
    totalRows: 0,
    chartIssueCount: 0,
    byCode: {},
    codeSeverity: {},
    severity: { critical: 0, warn: 0, info: 0 },
    chartIssues: [],
    childRollup: [],
    ...overrides,
  };
}

describe("formatHeadline", () => {
  it("uses the explicit zero form when nothing is wrong", () => {
    expect(formatHeadline(makeSummary({ totalRows: 5 }))).toBe(
      "0 of 5 rows have data gaps",
    );
  });

  it("omits the chart clause when chartIssueCount is 0", () => {
    expect(
      formatHeadline(makeSummary({ rowsWithGaps: 3, totalRows: 7 })),
    ).toBe("3 of 7 rows have data gaps");
  });

  it("renders both clauses joined with ' + '", () => {
    expect(
      formatHeadline(
        makeSummary({ rowsWithGaps: 3, totalRows: 7, chartIssueCount: 2 }),
      ),
    ).toBe("3 of 7 rows have data gaps + 2 chart-level issues");
  });

  it("uses singular 'issue' when chartIssueCount is exactly 1", () => {
    expect(
      formatHeadline(
        makeSummary({ rowsWithGaps: 0, totalRows: 7, chartIssueCount: 1 }),
      ),
    ).toBe("0 of 7 rows have data gaps + 1 chart-level issue");
  });

  it("renders both clauses even when row count is zero (chart-only failure)", () => {
    expect(
      formatHeadline(
        makeSummary({ rowsWithGaps: 0, totalRows: 1, chartIssueCount: 4 }),
      ),
    ).toBe("0 of 1 rows have data gaps + 4 chart-level issues");
  });
});

// ── formatSeverityLine ───────────────────────────────────

describe("formatSeverityLine", () => {
  it("renders 'clean' when all counts are zero", () => {
    expect(formatSeverityLine({ critical: 0, warn: 0, info: 0 })).toBe("clean");
  });

  it("omits zero buckets", () => {
    expect(formatSeverityLine({ critical: 2, warn: 0, info: 0 })).toBe("2 critical");
    expect(formatSeverityLine({ critical: 0, warn: 5, info: 0 })).toBe("5 warn");
    expect(formatSeverityLine({ critical: 0, warn: 0, info: 3 })).toBe("3 info");
  });

  it("joins multiple non-zero buckets with ' · '", () => {
    expect(formatSeverityLine({ critical: 1, warn: 2, info: 3 })).toBe(
      "1 critical · 2 warn · 3 info",
    );
  });
});

// ── formatCounterMarkup ──────────────────────────────────

describe("formatCounterMarkup", () => {
  it("renders the headline and severity line for clean data", () => {
    const html = renderToStaticMarkup(
      formatCounterMarkup(makeSummary({ totalRows: 3 })) as JSX.Element,
    );
    expect(html).toContain("0 of 3 rows have data gaps");
    expect(html).toContain("clean");
    expect(html).not.toContain("counter-breakdown");
  });

  it("sorts itemized codes alphabetically for deterministic output", () => {
    const summary = makeSummary({
      rowsWithGaps: 3,
      totalRows: 3,
      byCode: {
        "wi-overdue": [{ id: "1", title: "Z" }],
        "child-orphan": [{ id: "2", title: "A" }],
        "row-only-end-null": [{ id: "3", title: "M" }],
      },
    });
    const html = renderToStaticMarkup(formatCounterMarkup(summary) as JSX.Element);
    const childIdx = html.indexOf("child-orphan");
    const rowIdx = html.indexOf("row-only-end-null");
    const wiIdx = html.indexOf("wi-overdue");
    expect(childIdx).toBeGreaterThan(0);
    expect(rowIdx).toBeGreaterThan(childIdx);
    expect(wiIdx).toBeGreaterThan(rowIdx);
  });

  it("renders affected entities by title separated by commas", () => {
    const summary = makeSummary({
      rowsWithGaps: 2,
      totalRows: 2,
      byCode: {
        "wi-only-end-null": [
          { id: "a", title: "Alpha" },
          { id: "b", title: "Beta" },
        ],
      },
    });
    const html = renderToStaticMarkup(formatCounterMarkup(summary) as JSX.Element);
    expect(html).toContain("Alpha, Beta");
    expect(html).toContain("(2)");
  });
});

// ── formatCounterConsole ─────────────────────────────────

describe("formatCounterConsole", () => {
  const outputPath = "/Users/x/runway-gantts/foo.html";

  it("starts with the headline + severity line and ends with the absolute output path", () => {
    const out = formatCounterConsole(makeSummary({ totalRows: 5 }), outputPath);
    const lines = out.split("\n");
    expect(lines[0]).toBe("0 of 5 rows have data gaps");
    expect(lines[1]).toBe("  clean");
    expect(lines[lines.length - 1]).toBe(`Wrote: ${outputPath}`);
  });

  it("emits one indented line per issue code, alphabetically", () => {
    const summary = makeSummary({
      rowsWithGaps: 1,
      totalRows: 1,
      chartIssueCount: 1,
      byCode: {
        "wi-overdue": [{ id: "1", title: "Item" }],
        "l1-null-engagement-type": [{ id: "p", title: "Subject" }],
      },
      severity: { critical: 0, warn: 2, info: 0 },
    });
    const out = formatCounterConsole(summary, outputPath);
    const lines = out.split("\n");
    expect(lines[0]).toBe("0 of 1 rows have data gaps + 1 chart-level issue");
    expect(lines[1]).toBe("  2 warn");
    expect(lines[2]).toBe("  [l1-null-engagement-type] (1): Subject");
    expect(lines[3]).toBe("  [wi-overdue] (1): Item");
    expect(lines[4]).toBe(`Wrote: ${outputPath}`);
  });

  it("omits per-code lines when byCode is empty (clean run)", () => {
    const out = formatCounterConsole(makeSummary({ totalRows: 4 }), outputPath);
    expect(out.split("\n")).toEqual([
      "0 of 4 rows have data gaps",
      "  clean",
      `Wrote: ${outputPath}`,
    ]);
  });

  it("includes all affected titles comma-separated when a code has many refs", () => {
    const summary = makeSummary({
      rowsWithGaps: 3,
      totalRows: 3,
      byCode: {
        "wi-only-end-null": [
          { id: "a", title: "First" },
          { id: "b", title: "Second" },
          { id: "c", title: "Third" },
        ],
      },
      severity: { critical: 0, warn: 3, info: 0 },
    });
    const out = formatCounterConsole(summary, outputPath);
    expect(out).toContain("[wi-only-end-null] (3): First, Second, Third");
  });
});

