import { describe, expect, it } from "vitest";
import {
  computeBarGeometry,
  computeTodayPosition,
  renderGantt,
} from "./GanttTemplate";
import type {
  AnnotatedRow,
  AxisParams,
  ClientRow,
  GanttData,
  Issue,
  IssueCode,
  ProjectRow,
  RawData,
  Severity,
  Summary,
} from "./types";

const NOW = new Date("2026-04-28T00:00:00Z");

function makeClient(): ClientRow {
  return {
    id: "c1",
    name: "Test Client",
    slug: "test-client",
    nicknames: null,
    contractValue: null,
    contractTerm: null,
    contractStatus: null,
    team: null,
    clientContacts: null,
    createdAt: NOW,
    updatedAt: NOW,
  };
}

function makeProject(overrides: Partial<ProjectRow> = {}): ProjectRow {
  return {
    id: "p1",
    clientId: "c1",
    name: "Test Project",
    status: null,
    category: null,
    owner: null,
    resources: null,
    waitingOn: null,
    dueDate: null,
    startDate: null,
    endDate: null,
    contractStart: null,
    contractEnd: null,
    engagementType: null,
    parentProjectId: null,
    notes: null,
    staleDays: null,
    sortOrder: 0,
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

function makeRow(overrides: Partial<AnnotatedRow> = {}): AnnotatedRow {
  return {
    kind: "weekitem",
    id: "w1",
    title: "Item",
    owner: null,
    resources: null,
    startDate: null,
    endDate: null,
    status: null,
    category: null,
    weekOf: null,
    inline: [],
    subRow: [],
    ...overrides,
  } as AnnotatedRow;
}

function mkIssue(code: IssueCode, severity: Severity = "warn", message = "msg"): Issue {
  return { code, message, severity };
}

function emptySummary(overrides: Partial<Summary> = {}): Summary {
  return {
    rowsWithGaps: 0,
    totalRows: 0,
    chartIssueCount: 0,
    byCode: {},
    codeSeverity: {},
    severity: { critical: 0, warn: 0, info: 0 },
    chartIssues: [],
    childRollup: [],
    ...overrides,
  };
}

const weeklyAxis: AxisParams = {
  kind: "weekly",
  start: "2026-04-13",
  end: "2026-05-25",
  today: "2026-04-28",
  columns: [
    { date: "2026-04-13", label: "4/13" },
    { date: "2026-04-20", label: "4/20" },
    { date: "2026-04-27", label: "4/27" },
    { date: "2026-05-04", label: "5/4" },
    { date: "2026-05-11", label: "5/11" },
    { date: "2026-05-18", label: "5/18" },
  ],
};

// ── Geometry ─────────────────────────────────────────────

describe("computeBarGeometry", () => {
  it("returns bar geometry with positive left + width for a normal range", () => {
    const row = makeRow({ startDate: "2026-04-20", endDate: "2026-04-26" });
    const geom = computeBarGeometry(row, weeklyAxis);
    expect(geom.kind).toBe("bar");
    if (geom.kind === "bar") {
      expect(geom.left).toBeGreaterThan(0);
      expect(geom.left).toBeLessThan(50);
