// ── Client rundown (single-page, multi-section) ───────────

export type RundownSectionKind = "wrapper" | "wrapper-child" | "standalone";

export type RundownSection = {
  anchor: string; // slug for the in-page #anchor jump
  kind: RundownSectionKind;
  title: string;
  parentTitle?: string; // for wrapper-child: the wrapper's name
  data: GanttData;
};

export type ClientRundownData = {
  client: ClientRow;
  sections: RundownSection[];
  generatedAt: string; // YYYY-MM-DD
  overallSeverity: SeverityCounts;
};

content:
/**
 * Client rundown — assembles a single-page, multi-section view of every
 * top-level project under a client.
 *
 * Section layout per operator (2026-04-30):
 *   - Wrapper retainer (e.g. "1H Convergix Retainer"):
 *       1 wrapper section showing wrapper-level chart issues + a visual
 *       Gantt of the children L1 projects (no per-row alert sub-rows on
 *       the rollup itself — those move to each child's section).
 *       N "wrapper-child" sections — one per child L1, drilling into
 *       that child's L2 weekItems with full L1+L2 detection.
 *   - Standalone L1: a single "standalone" section.
 *
 * Each top-level project contributes one or more sections. Order is
 * alphabetical by top-level project name; within a wrapper, the wrapper
 * section precedes its children which are themselves alphabetical.
 */

import { drizzle } from "drizzle-orm/libsql";
import { eq, inArray } from "drizzle-orm";
import { weekItems, projects as projectsTable } from "@/lib/db/runway-schema";
import {
  detectChildProjectIssues,
  detectL1Issues,
  detectWeekItemIssues,
  detectWrapperIssues,
} from "./detect-issues";
import { computeAxis, formatDateRange, transformRows } from "./transform-rows";
import { summarize } from "./counter";
import type {
  AnnotatedRow,
  ClientRow,
  ClientRundownData,
  GanttData,
  GanttRow,
  Issue,
  ProjectRow,
  RawData,
  RundownSection,
  SeverityCounts,
  WeekItemRow,
} from "./types";

type DrizzleDb = ReturnType<typeof drizzle>;

const ZERO: SeverityCounts = { critical: 0, warn: 0, info: 0 };

function slugAnchor(input: string): string {
  return input
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

/**
 * Build a single-section GanttData for a project entity. Used both for
 * standalone L1s and for drilling into a wrapper-child. `extraChartIssues`
 * lets the wrapper-child path append its relational issues (parent-date
 * mismatch etc.) on the child's own section instead of the rollup.
 */
function buildL1SectionData(
  entity: ProjectRow,
  client: ClientRow,
  weekItemsForEntity: WeekItemRow[],
  todayISO: string,
  generatedAt: string,
  extraChartIssues: Issue[] = [],
): GanttData {
  const raw: RawData = { kind: "l1", entity, client, children: weekItemsForEntity };
  const rows = transformRows(raw);
  const axis = computeAxis(raw, rows, new Date(`${todayISO}T00:00:00Z`));
  const itemById = new Map(weekItemsForEntity.map((w) => [w.id, w]));
  const annotated: AnnotatedRow[] = rows.map((row) => {
    if (row.kind !== "weekitem") return { ...row, inline: [], subRow: [] };
    const item = itemById.get(row.id);
    if (!item) return { ...row, inline: [], subRow: [] };
    return { ...row, ...detectWeekItemIssues(item, entity, todayISO) };
  });
  const chartIssues = [
    ...detectL1Issues(entity, weekItemsForEntity.length),
    ...extraChartIssues,
  ];
  const headerRange = formatDateRange(entity.startDate, entity.endDate);
  return {
    raw,
    rows: annotated,
    chartIssues,
    axis,
    headerRange,
    generatedAt,
    summary: summarize({ rows: annotated, chartIssues, entity }),
  };
}

/**
 * Wrapper rollup section — chart issues are wrapper-level only. Rows show
 * the children L1s as visual Gantt rows but with NO per-row inline or
 * sub-row alerts (those move to each child's drill-in section).
 */
function buildWrapperSectionData(
  wrapper: ProjectRow,
  client: ClientRow,
  childProjects: ProjectRow[],
  orphanWeekItems: { id: string; title: string }[],
  generatedAt: string,
  todayISO: string,
): GanttData {
  const raw: RawData = {
    kind: "wrapper",
    entity: wrapper,
    client,
    children: childProjects,
    orphanWeekItems,
  };
  const baseRows: GanttRow[] = transformRows(raw);
  const axis = computeAxis(raw, baseRows, new Date(`${todayISO}T00:00:00Z`));
  // Suppress per-row alerts on the rollup — operator-locked.
  const annotated: AnnotatedRow[] = baseRows.map((row) => ({
    ...row,
    inline: [],
    subRow: [],
  }));
  const chartIssues = detectWrapperIssues(wrapper, childProjects, orphanWeekItems);
  const headerRange = formatDateRange(wrapper.startDate, wrapper.endDate);
  return {
    raw,
    rows: annotated,
    chartIssues,
    axis,
    headerRange,
    generatedAt,
    summary: summarize({ rows: annotated, chartIssues, entity: wrapper }),
  };
}

function addSeverity(target: SeverityCounts, src: SeverityCounts): void {
  target.critical += src.critical;
  target.warn += src.warn;
  target.info += src.info;
}

/**
 * Build the complete rundown for a client. Fetches each top-level
 * project's child projects (to classify wrapper vs L1) and, for any L1
 * subject (standalone OR wrapper-child), its weekItems.
 *
 * One round trip per top-level project for child-projects, then a single
 * batch query for weekItems across all entities that need them.
 */
export async function extractClientRundown(
  db: DrizzleDb,
  client: ClientRow,
  topLevelProjects: ProjectRow[],
  generatedAt: string,
  todayISO: string,
): Promise<ClientRundownData> {
  // Stable alphabetical order across runs.
  const ordered = [...topLevelProjects].sort((a, b) => a.name.localeCompare(b.name));

  // First pass: classify each top-level into wrapper-with-children OR
  // standalone, and collect the universe of project ids that need
  // weekItems fetched (all standalones + every wrapper-child + every
  // wrapper itself for orphan-probe).
  type ClassifiedTop =
    | { kind: "wrapper"; project: ProjectRow; children: ProjectRow[] }
    | { kind: "standalone"; project: ProjectRow };

  const classified: ClassifiedTop[] = [];
  for (const top of ordered) {
    const children = await db
      .select()
      .from(projectsTable)
      .where(eq(projectsTable.parentProjectId, top.id));
    if (
      top.parentProjectId === null &&
      top.engagementType === "retainer" &&
      children.length > 0
    ) {
      classified.push({ kind: "wrapper", project: top, children });
    } else {
      classified.push({ kind: "standalone", project: top });
    }
  }

  // Collect every project id that needs a weekItems pull.
  const idsNeedingWeekItems = new Set<string>();
  for (const c of classified) {
    if (c.kind === "wrapper") {
      idsNeedingWeekItems.add(c.project.id); // for orphan probe
      for (const child of c.children) idsNeedingWeekItems.add(child.id);
    } else {
      idsNeedingWeekItems.add(c.project.id);
    }
  }

  const wiByProject = new Map<string, WeekItemRow[]>();
  if (idsNeedingWeekItems.size > 0) {
    const all = await db
      .select()
      .from(weekItems)
      .where(inArray(weekItems.projectId, Array.from(idsNeedingWeekItems)));
    for (const w of all) {
      const pid = w.projectId;
      if (!pid) continue;
      const arr = wiByProject.get(pid);
      if (arr) arr.push(w);
      else wiByProject.set(pid, [w]);
    }
  }

  const sections: RundownSection[] = [];
  const overall: SeverityCounts = { ...ZERO };

  for (const c of classified) {
    if (c.kind === "wrapper") {
      const orphanItems = (wiByProject.get(c.project.id) ?? []).map((w) => ({
        id: w.id,
        title: w.title,
      }));
      const wrapperData = buildWrapperSectionData(
        c.project,
        client,
        c.children,
        orphanItems,
        generatedAt,
        todayISO,
      );
      sections.push({
        anchor: slugAnchor(c.project.name),
        kind: "wrapper",
        title: c.project.name,
        data: wrapperData,
      });
      addSeverity(overall, wrapperData.summary.severity);

      // Per-child drill-in sections
      const sortedChildren = [...c.children].sort((a, b) =>
        a.name.localeCompare(b.name),
      );
      for (const child of sortedChildren) {
        const wis = wiByProject.get(child.id) ?? [];
        // Append child-of-wrapper relational issues to the child's chart
        // issues — these describe the child's relationship to the
        // wrapper, so they belong under the child's section rather than
        // the rollup (operator semantic 2026-04-30).
        const relationship = detectChildProjectIssues(child, c.project);
        const extraChart = [...relationship.inline, ...relationship.subRow];
        const childData = buildL1SectionData(
          child,
          client,
          wis,
          todayISO,
          generatedAt,
          extraChart,
        );
        sections.push({
          anchor: slugAnchor(`${c.project.name}-${child.name}`),
          kind: "wrapper-child",
          title: child.name,
          parentTitle: c.project.name,
          data: childData,
        });
        addSeverity(overall, childData.summary.severity);
      }
    } else {
      const wis = wiByProject.get(c.project.id) ?? [];
      const data = buildL1SectionData(
        c.project,
        client,
        wis,
        todayISO,
        generatedAt,
      );
      sections.push({
        anchor: slugAnchor(c.project.name),
        kind: "standalone",
        title: c.project.name,
        data,
      });
      addSeverity(overall, data.summary.severity);
    }
  }

  return {
    client,
    sections,
    generatedAt,
    overallSeverity: overall,
  };
}

